// Edit these to control the generated titles.
// min_length / max_length are character counts, including spaces.
const settings = {
  min_length: 50,
  max_length: 120,
  max_attempts: 3,
  rules: [
    "Start the title with the brand name",
    "Follow this order: brand, product line or variety, growing conditions or use, product type, then search keywords",
    "Use title case",
    "Separate related product types with a slash and no spaces, for example Fertilizer/Seed/Soil Improver",
    "Do not use commas or hyphens as separators",
    "End the title with keywords shoppers search for, without repeating words already in the title",
    "Do not include the MPN or SKU",
    "Do not use promotional words such as best, sale, new, free shipping, or guaranteed",
    "Do not use all caps, emojis, or symbols such as ! * $ ® ™",
    "Only include attributes that appear in the source data. Do not invent specifications"
  ],
  // Example titles that show the style you want. Each is a plain string.
  examples: [
    "{brand} Tall Fescue Grass Sun or Shade Fertilizer/Seed/Soil Improver {keywords}"
  ]
};

return [{ json: { ...$input.first().json, ...settings } }];

// Universal Search response shape can vary, so probe common containers.
// Emit one item per candidate URL (top 3) so each can be scraped and checked
// with product matching in turn.
const product = $('Sample Product').first().json;
const res = $input.first().json;

let list = res.results || res.data || res.items || res.pages || res.urls || [];
if (!Array.isArray(list) && Array.isArray(res)) list = res;
if (!Array.isArray(list)) list = [];

const urls = list
  .map(r => (typeof r === 'string') ? r : (r.url || r.link || r.source_url || r.page_url || ''))
  .filter(Boolean)
  .slice(0, 3);

return urls.map((source_url, i) => ({
  json: {
    ...product,
    source_url,
    candidate_rank: i + 1
  }
}));

