// Build the title request from the matched page's scrape, the rules,
// and the examples in Title Settings.
const settings = $('Title Settings').first().json;
const candidate = $('Loop Over Candidates').item.json;
const scraped = $('Smart Scrape').item.json || {};
const s = scraped.data || scraped.result || scraped;

// Scraped title goes in `title`. Everything else scraped from the page
// (description, specs, brand, MPN, etc.) goes in `description`.
const toText = v => (v == null || v === '') ? '' : (typeof v === 'string' ? v : JSON.stringify(v));
const imageKeys = ['image_urls', 'image_url', 'images'];
const details = Object.entries(s)
  .filter(([k, v]) => k !== 'title' && k !== 'description' && !imageKeys.includes(k) && toText(v))
  .map(([k, v]) => `${k}: ${toText(v)}`);
const description = [toText(s.description), ...details].filter(Boolean).join('\n');

let image_url = '';
if (Array.isArray(s.image_urls)) image_url = s.image_urls[0] || '';
else if (s.image_url) image_url = s.image_url;
else if (Array.isArray(s.images)) image_url = s.images[0] || '';

return [{
  json: {
    product: {
      title: s.title || candidate.title || '',
      description,
      image_url
    },
    customer_rules: [
      ...settings.rules,
      `Keep the title between ${settings.min_length} and ${settings.max_length} characters, including spaces`,
      `The brand is "${candidate.brand}"`
    ],
    examples: settings.examples,
    candidate: {
      title: candidate.title,
      brand: candidate.brand,
      mpn: candidate.mpn,
      source_url: candidate.source_url
    }
  }
}];

// Check the generated title against the length limits.
// Each run of this node is one attempt.
const settings = $('Title Settings').first().json;
const res = $input.first().json;
const raw = res.product_title ?? res.title ?? res;
const title = (typeof raw === 'string' ? raw : '').trim();
const length = title.length;
const attempt = $runIndex + 1;

let issue = '';
if (!title) issue = 'empty';
else if (length < settings.min_length) issue = 'too_short';
else if (length > settings.max_length) issue = 'too_long';

return [{
  json: {
    title,
    length,
    min_length: settings.min_length,
    max_length: settings.max_length,
    attempt,
    valid: issue === '',
    issue,
    can_retry: attempt < settings.max_attempts
  }
}];

// Resend the original request with an extra rule telling the model
// how far off the last title was.
const base = $('Build Title Request').first().json;
const v = $input.first().json;

const feedback = v.issue === 'empty'
  ? `The previous attempt returned no title. Write a title between ${v.min_length} and ${v.max_length} characters`
  : `The previous title "${v.title}" was ${v.length} characters, which is too ${v.issue === 'too_long' ? 'long' : 'short'}. Rewrite it to be between ${v.min_length} and ${v.max_length} characters, including spaces`;

return [{
  json: {
    ...base,
    customer_rules: [...base.customer_rules, feedback]
  }
}];

// Final record. Titles that never passed the length check are
// returned with status "needs_review" instead of being dropped.
const v = $input.first().json;
const request = $('Build Title Request').first().json;
const candidate = request.candidate;

return [{
  json: {
    mpn: candidate.mpn,
    brand: candidate.brand,
    source_url: candidate.source_url,
    original_title: candidate.title,
    scraped_title: request.product.title,
    optimized_title: v.title,
    title_length: v.length,
    attempts: v.attempt,
    status: v.valid ? 'valid' : 'needs_review',
    issue: v.issue
  }
}];
